{
  "contract": "GoodMorning",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions can indirectly trigger swapBack through token transfers."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "require(!inSwap)",
      "to_marker": "inSwap = true"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "inSwap = true",
      "to_marker": "inSwap = false"
    },
    "post": {
      "name": "post",
      "from_marker": "inSwap = false",
      "to_marker": "require(swapThreshold > 0)"
    },
    "linearization_point": "inSwap = false"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of _rOwned in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The exposure invariant ensures that the sum of _rOwned is conserved across the callback window, accounting for in-flight changes."
  }
}
